<div class="mx-auto max-w-4xl space-y-6"><div><h1 class="text-2xl font-bold">School licence</h1><p class="mt-1 text-sm text-slate-500">Licence status controls whether this school is a demo, trial, or licensed Edlink institution.</p></div>@if(session('status'))<div class="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">{{session('status')}}</div>@endif@if($errors->any())<div class="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800">@foreach($errors->all() as $error)<div>{{ $error }}</div>@endforeach</div>@endif@if($canManage)<label class="block text-sm font-medium">School<select wire:model.live="schoolId" class="mt-1 w-full rounded-xl border-slate-200">@foreach($schools as $item)<option value="{{ $item->id }}">{{ $item->name }} ({{ $item->school_number }})</option>@endforeach</select></label>@endif<form wire:submit="save" class="rounded-2xl border bg-white p-6 shadow-sm"><div class="mb-5 flex items-center justify-between"><div><h2 class="font-bold">{{ $school->name }}</h2><p class="text-sm text-slate-500">{{ $school->school_number }}</p></div><span class="rounded-full px-3 py-1 text-sm font-bold {{ $school->license_status === 'active' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700' }}">{{ ucfirst($school->license_status) }}</span></div><div class="grid gap-4 md:grid-cols-2"><label class="text-sm font-medium">Plan<select wire:model="license_plan" @disabled(!$canManage) class="mt-1 w-full rounded-xl border-slate-200"><option value="basic">Basic</option><option value="premium">Premium</option><option value="enterprise">Enterprise</option></select></label><label class="text-sm font-medium">Status<select wire:model="license_status" @disabled(!$canManage) class="mt-1 w-full rounded-xl border-slate-200"><option value="active">Active</option><option value="trial">Trial</option><option value="suspended">Suspended</option><option value="expired">Expired</option></select></label><label class="text-sm font-medium">Licence starts<input wire:model="license_started_at" @disabled(!$canManage) type="date" class="mt-1 w-full rounded-xl border-slate-200"></label><label class="text-sm font-medium">Licence expires<input wire:model="license_expires_at" @disabled(!$canManage) type="date" class="mt-1 w-full rounded-xl border-slate-200"></label><label class="text-sm font-medium">Student limit<input wire:model="license_student_limit" @disabled(!$canManage) type="number" min="1" placeholder="No limit" class="mt-1 w-full rounded-xl border-slate-200"></label><label class="mt-6 flex items-center gap-2 text-sm font-medium"><input wire:model="is_demo" @disabled(!$canManage) type="checkbox"> Demo environment</label></div>@if($canManage)<button class="mt-6 rounded-xl bg-yellow-400 px-5 py-3 text-sm font-bold">Save licence</button>@else<p class="mt-6 rounded-xl bg-slate-50 p-3 text-sm text-slate-600">Your school administrator can view this status. Licence changes and demo extensions are managed by the Edlink platform administrator.</p>@endif</form></div>
